mapper.select:
SELECT 
     , f_cdnm('AfterStateCode', ics17_state_cd, ics17_company_id, f_sysdate()) AS state_name
     , f_emp_kor_nm(ics17_person_id)                                           AS person_name
     , sys01_company_nm                                                        AS company_name
  FROM ics17_user_request
       INNER JOIN sys01_company ON ics17_company_id = sys01_company_id
 WHERE sys01_company_nm LIKE #{companyText}

   AND COALESCE(ics17_state_cd, ' ') NOT IN ('10','90')


   AND COALESCE(ics17_state_cd, ' ') LIKE #{stateCode}

   AND COALESCE(ics17_confirm_yn, 'false') LIKE #{confirmYn}
   AND f_trunc(ics17_reg_date) BETWEEN #{startDate}::date AND #{closeDate}::date
   AND CONCAT(f_emp_kor_nm(ics17_person_id), ics17_law_title, ics17_law_content) LIKE #{searchText}
 ORDER BY ics17_reg_date DESC

SELECT 
     , f_cdnm('AfterStateCode', ics17_state_cd, ics17_company_id, f_sysdate()) AS state_name
     , f_emp_kor_nm(ics17_person_id)                                           AS person_name
     , f_get_company_nm(ics17_company_id)                                      AS company_name
  FROM ics17_user_request
 WHERE ics17_company_id = #{companyId}


   AND COALESCE(ics17_state_cd, ' ') LIKE #{stateCode}


   AND COALESCE(ics17_state_cd, ' ') NOT IN ('10','90')


   AND CONCAT(ics17_law_title, ics17_law_content) LIKE #{searchText}
   AND COALESCE(ics17_confirm_yn, 'false') LIKE #{confirmYn}
   AND f_trunc(ics17_reg_date) BETWEEN #{startDate}::date AND #{closeDate}::date
 ORDER BY ics17_reg_date DESC

mapper.update:
UPDATE ics17_user_request
   SET ics17_reg_date     = #{req.regDate}::date,
       ics17_law_title    = #{req.lawTitle},
       ics17_law_content  = #{req.lawContent},
       ics17_submit_to    = #{req.submitTo},
       ics17_related_law  = #{req.relatedLaw},
       ics17_report_cycle = #{req.reportCycle},
       ics17_confirm_yn   = #{req.confirmYn}
 WHERE ics17_user_request_id = #{userRequestId}
   AND ics17_company_id      = #{companyId}

mapper.delete:
DELETE FROM ics17_user_request
 WHERE ics17_user_request_id = #{userRequestId}
   AND ics17_company_id      = #{companyId}

